333	            }
334	            for i in 0..node.child_count() {
335	                if let Some(child) = node.child(i) {
336	                    stack.push(child);
337	                }
338	            }
339	        }
340	        let class = class_node.expect("class_declaration not found");
341	        let bases = extract_inheritance(&class, src);
