     3	//! Language detection by file extension.
     4	//!
     5	//! Maps file extensions to supported language identifiers.
     6	//!
     7	//! All languages are unconditionally compiled in.  The historical `lang-*` Cargo feature
     8	//! gates have been removed; every registered extension is always available at runtime.
     9	//! This simplifies the build matrix and guarantees that callers never get a feature-gate
    10	//! error for a language that "should" be supported.
    11	
    12	const EXTENSION_MAP: &[(&str, &str)] = &[
    13	    ("c", "c"),
    14	    ("cc", "cpp"),
    15	    ("cjs", "javascript"),
    16	    ("cpp", "cpp"),
    17	    ("cxx", "cpp"),
    18	    ("f", "fortran"),
    19	    ("f03", "fortran"),
    20	    ("f08", "fortran"),
    21	    ("f77", "fortran"),
    22	    ("f90", "fortran"),
    23	    ("f95", "fortran"),
    24	    ("for", "fortran"),
    25	    ("ftn", "fortran"),
    26	    ("h", "cpp"),
    27	    ("cs", "csharp"),
    28	    ("hpp", "cpp"),
    29	    ("hxx", "cpp"),
    30	    ("js", "javascript"),
    31	    ("mjs", "javascript"),
    32	    ("go", "go"),
    33	    ("java", "java"),
    34	    ("kt", "kotlin"),
    35	    ("kts", "kotlin"),
    36	    ("py", "python"),
    37	    ("rs", "rust"),
    38	    ("ts", "typescript"),
    39	    ("tsx", "tsx"),
    40	    ("html", "html"),
    41	    ("htm", "html"),
    42	    ("md", "markdown"),
    43	    ("mdx", "markdown"),
    44	    ("astro", "astro"),
    45	    ("css", "css"),
    46	    ("yaml", "yaml"),
    47	    ("yml", "yaml"),
    48	    ("json", "json"),
    49	    ("toml", "toml"),
    50	    ("swift", "swift"),
    51	];
    52	
    53	/// Returns the language identifier for the given file extension, or `None` if unsupported.
    54	///
    55	/// The lookup is case-insensitive. Supported extensions include `rs`, `py`, `go`, `java`,
    56	/// `ts`, `tsx`, `js`, `mjs`, `cjs`, `c`, `cc`, `cpp`, `cxx`, `h`, `hpp`, `hxx`, `cs`,
    57	/// Fortran variants `f`, `f77`, `f90`, `f95`, `f03`, `f08`, `for`, `ftn`,
    58	/// HTML variants `html`, `htm`, and Markdown variants `md`, `mdx`.
    59	#[must_use]
    60	pub fn language_for_extension(ext: &str) -> Option<&'static str> {
    61	    EXTENSION_MAP
    62	        .iter()
    63	        .find(|(e, _)| e.eq_ignore_ascii_case(ext))
    64	        .map(|(_, lang)| *lang)
    65	}
    66	
    67	/// Returns all file extensions supported by the compiled feature set.
    68	///
    69	/// Each entry corresponds to one row in `EXTENSION_MAP`. The list is used to
    70	/// build human-readable error messages without duplicating the extension list.
    71	#[must_use]
    72	pub fn supported_extensions() -> Vec<&'static str> {
    73	    EXTENSION_MAP.iter().map(|(ext, _)| *ext).collect()
    74	}
    75	
    76	/// Returns a static slice of all supported language names.
    77	///
    78	/// All languages are unconditionally compiled in; the historical `lang-*` feature
    79	/// gates have been removed.
    80	#[must_use]
    81	pub fn supported_languages() -> &'static [&'static str] {
    82	    &[
    83	        "rust",
    84	        "go",
    85	        "java",
    86	        "kotlin",
    87	        "python",
    88	        "typescript",
    89	        "tsx",
    90	        "javascript",
    91	        "fortran",
    92	        "c",
    93	        "cpp",
    94	        "csharp",
    95	        "html",
    96	        "markdown",
    97	        "swift",
    98	    ]
    99	}
   100	
   101	#[cfg(test)]
   102	mod tests {
   103	    use super::*;
   104	
   105	    #[test]
   106	    fn test_language_for_extension_happy_path() {
   107	        assert_eq!(language_for_extension("rs"), Some("rust"));
   108	        assert_eq!(language_for_extension("py"), Some("python"));
   109	        assert_eq!(language_for_extension("go"), Some("go"));
   110	        assert_eq!(language_for_extension("java"), Some("java"));
   111	        assert_eq!(language_for_extension("ts"), Some("typescript"));
   112	        assert_eq!(language_for_extension("tsx"), Some("tsx"));
   113	        assert_eq!(language_for_extension("swift"), Some("swift"));
   114	        assert_eq!(language_for_extension("f90"), Some("fortran"));
   115	        assert_eq!(language_for_extension("for"), Some("fortran"));
   116	        assert_eq!(language_for_extension("ftn"), Some("fortran"));
   117	        assert_eq!(language_for_extension("c"), Some("c"));
   118	        assert_eq!(language_for_extension("cpp"), Some("cpp"));
   119	        assert_eq!(language_for_extension("h"), Some("cpp"));
   120	        assert_eq!(language_for_extension("hpp"), Some("cpp"));
   121	        assert_eq!(language_for_extension("cc"), Some("cpp"));
   122	        assert_eq!(language_for_extension("kt"), Some("kotlin"));
   123	        assert_eq!(language_for_extension("kts"), Some("kotlin"));
   124	    }
   125	
   126	    /// The schema pattern must stay ECMAScript-valid (JSON Schema clients
   127	    /// validate with ECMAScript regexes, so the pattern uses `[Xx]`
   128	    /// per-character classes instead of `(?i)`): every supported extension
   129	    /// must match and an unsupported one must not.
   130	    #[test]
   131	    #[cfg(feature = "schemars")]
   132	    fn test_supported_file_ext_pattern_covers_all_extension_map_entries() {
   133	        let pattern = crate::schema_helpers::supported_file_ext_pattern();
   134	        assert!(!pattern.contains("(?i)"), "ECMAScript rejects (?i)");
   135	        let re = regex::Regex::new(&format!("(?i){pattern}")).unwrap();
   136	        for ext in supported_extensions() {
   137	            assert!(
   138	                re.is_match(&format!("src/file.{ext}")),
   139	                "pattern does not match supported extension '{ext}'"
   140	            );
   141	            assert!(
   142	                re.is_match(&format!("SRC/FILE.{}", ext.to_uppercase())),
   143	                "pattern is not case-insensitive for '{ext}'"
   144	            );
   145	        }
   146	        assert!(!re.is_match("src/file.txt"));
   147	        assert!(!re.is_match("src/file.rss"));
   148	    }
   149	
   150	    #[test]
   151	    fn test_language_for_extension_edge_case() {
   152	        assert_eq!(language_for_extension("unknown"), None);
   153	        assert_eq!(language_for_extension(""), None);
   154	        assert_eq!(language_for_extension("RS"), Some("rust"));
   155	        // Uppercase Fortran extensions resolved via eq_ignore_ascii_case
   156	        assert_eq!(language_for_extension("F90"), Some("fortran"));
   157	        assert_eq!(language_for_extension("FOR"), Some("fortran"));
   158	    }
   159	}
