     3	//! Swift language handler: queries and inheritance extraction.
     4	
     5	/// Tree-sitter query for extracting Swift elements (classes, structs, functions, protocols).
     6	pub const ELEMENT_QUERY: &str = r"
     7	(class_declaration
     8	  name: (type_identifier) @class_name) @class
     9	(function_declaration
    10	  name: (simple_identifier) @function_name) @function
    11	(protocol_declaration
    12	  name: (type_identifier) @protocol_name) @class
    13	";
    14	
    15	/// Tree-sitter query for extracting function calls.
    16	pub const CALL_QUERY: &str = r"
    17	(call_expression
    18	  (simple_identifier) @call)
    19	";
    20	
    21	/// Tree-sitter query for extracting type references.
    22	pub const REFERENCE_QUERY: &str = r"
    23	(type_identifier) @type_ref
    24	";
    25	
    26	/// Tree-sitter query for extracting Swift imports.
    27	pub const IMPORT_QUERY: &str = r"
    28	(import_declaration) @import_path
    29	";
    30	
    31	/// Tree-sitter query for extracting definition and use sites.
    32	pub const DEFUSE_QUERY: &str = r"
    33	(property_declaration
    34	  (pattern
    35	    (simple_identifier) @write.property))
    36	(simple_identifier) @read.usage
    37	";
    38	
    39	use tree_sitter::Node;
    40	
    41	use crate::languages::get_node_text;
    42	
    43	/// Extract inheritance information from a Swift class declaration node.
    44	///
    45	/// Walks `inheritance_specifier` children of the class declaration. The first
    46	/// specifier is conventionally the superclass; subsequent specifiers are
    47	/// protocol conformances. Results use `extends`/`conforms` prefixes.
    48	#[must_use]
    49	pub fn extract_inheritance(node: &Node, source: &str) -> Vec<String> {
    50	    if node.kind() != "class_declaration" {
    51	        return Vec::new();
    52	    }
    53	
    54	    let mut inherits = Vec::new();
    55	    let mut seen_superclass = false;
    56	
    57	    for i in 0..node.child_count() {
    58	        if let Some(child) = node.child(i)
    59	            && child.kind() == "inheritance_specifier"
    60	            && let Some(type_node) = child.named_child(0)
    61	            && let Some(text) = get_node_text(&type_node, source)
    62	        {
    63	            // The superclass may carry generic arguments; keep the base name only.
    64	            let base = text.split('<').next().unwrap_or(&text).trim().to_string();
    65	            if seen_superclass {
    66	                inherits.push(format!("conforms {base}"));
    67	            } else {
    68	                inherits.push(format!("extends {base}"));
    69	                seen_superclass = true;
    70	            }
    71	        }
    72	    }
    73	
    74	    inherits
    75	}
    76	
    77	#[cfg(test)]
    78	mod tests {
    79	    use super::*;
    80	    use tree_sitter::{Parser, StreamingIterator};
